import Sidebar from "../components/Sidebar";
import { useState, useEffect } from "react";

function TaskManager() {

  const [task, setTask] = useState("");

  const [tasks, setTasks] = useState(() => {

    const savedTasks =
      localStorage.getItem("tasks");

    return savedTasks
      ? JSON.parse(savedTasks)
      : [];

  });

  // SAVE TASKS TO LOCAL STORAGE
  useEffect(() => {

    localStorage.setItem(
      "tasks",
      JSON.stringify(tasks)
    );

  }, [tasks]);

  // ADD TASK
  const addTask = () => {

    if (task.trim() === "") {
      return;
    }

    const newTask = {
      text: task,
      completed: false,
    };

    setTasks([...tasks, newTask]);

    setTask("");
  };

  // COMPLETE TASK
  const toggleComplete = (index) => {

    const updatedTasks = [...tasks];

    updatedTasks[index].completed =
      !updatedTasks[index].completed;

    setTasks(updatedTasks);
  };

  // DELETE TASK
  const deleteTask = (index) => {

    const updatedTasks =
      tasks.filter((_, i) => i !== index);

    setTasks(updatedTasks);
  };

  return (
    <div style={{ display: "flex" }}>

      <Sidebar />

      <div style={container}>

        <h1 style={heading}>
          Task Manager ✅
        </h1>

        <div style={inputCard}>

          <input
            type="text"
            placeholder="Enter Task"
            value={task}
            onChange={(e) => setTask(e.target.value)}
            style={inputStyle}
          />

          <button
            style={buttonStyle}
            onClick={addTask}
          >
            Add Task
          </button>

        </div>

        <div style={taskContainer}>

          {tasks.length === 0 ? (

            <p style={emptyText}>
              No Tasks Added
            </p>

          ) : (

            tasks.map((item, index) => (

              <div key={index} style={taskCard}>

                <h3
                  style={{
                    textDecoration:
                      item.completed
                        ? "line-through"
                        : "none",

                    opacity:
                      item.completed
                        ? 0.6
                        : 1,
                  }}
                >
                  {item.text}
                </h3>

                <div style={buttonGroup}>

                  <button
                    style={
                      item.completed
                        ? undoButton
                        : completeButton
                    }
                    onClick={() =>
                      toggleComplete(index)
                    }
                  >
                    {item.completed
                      ? "Undo"
                      : "Complete"}
                  </button>

                  <button
                    style={deleteButton}
                    onClick={() =>
                      deleteTask(index)
                    }
                  >
                    Delete
                  </button>

                </div>

              </div>

            ))

          )}

        </div>

      </div>

    </div>
  );
}

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg, #6366F1, #8B5CF6)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const inputCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "25px",
  borderRadius: "20px",
  display: "flex",
  gap: "15px",
  flexWrap: "wrap",
};

const inputStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  flex: 1,
  minWidth: "200px",
  fontSize: "16px",
};

const buttonStyle = {
  padding: "14px 25px",
  background: "#111827",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
};

const taskContainer = {
  marginTop: "30px",
  display: "flex",
  flexDirection: "column",
  gap: "20px",
};

const taskCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "20px",
  borderRadius: "20px",
  color: "white",
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  flexWrap: "wrap",
};

const buttonGroup = {
  display: "flex",
  gap: "10px",
};

const completeButton = {
  padding: "10px 15px",
  background: "#10B981",
  border: "none",
  borderRadius: "10px",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

const undoButton = {
  padding: "10px 15px",
  background: "#F59E0B",
  border: "none",
  borderRadius: "10px",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

const deleteButton = {
  padding: "10px 15px",
  background: "#EF4444",
  border: "none",
  borderRadius: "10px",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

const emptyText = {
  color: "white",
  textAlign: "center",
  marginTop: "40px",
  fontSize: "18px",
};

export default TaskManager;