import Sidebar from "../components/Sidebar";
import { useEffect, useState } from "react";

import {
  PieChart,
  Pie,
  Cell,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from "recharts";

function Analytics() {
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    const savedTasks = JSON.parse(localStorage.getItem("tasks"));

    if (savedTasks) {
      setTasks(savedTasks);
    }
  }, []);

  const totalTasks = tasks.length;

  const completedTasks = tasks.filter((task) => task.completed).length;

  const pendingTasks = totalTasks - completedTasks;

  const productivity =
    totalTasks === 0
      ? 0
      : Math.round((completedTasks / totalTasks) * 100);

  // 📊 PIE DATA
  const taskData = [
    { name: "Completed", value: completedTasks },
    { name: "Pending", value: pendingTasks },
  ];

  // 📈 LINE DATA (mock trend)
  const productivityData = [
    { day: "Mon", value: 40 },
    { day: "Tue", value: 55 },
    { day: "Wed", value: 65 },
    { day: "Thu", value: 70 },
    { day: "Fri", value: productivity },
  ];

  return (
    <div style={{ display: "flex" }}>
      <Sidebar />

      <div style={container}>
        <h1 style={heading}>Analytics Dashboard 📊</h1>

        {/* STATS CARDS */}
        <div style={cardContainer}>
          <div style={card}>
            <h2>Total Tasks</h2>
            <p style={numberStyle}>{totalTasks}</p>
          </div>

          <div style={card}>
            <h2>Completed Tasks</h2>
            <p style={numberStyle}>{completedTasks}</p>
          </div>

          <div style={card}>
            <h2>Pending Tasks</h2>
            <p style={numberStyle}>{pendingTasks}</p>
          </div>

          <div style={card}>
            <h2>Productivity</h2>
            <p style={numberStyle}>{productivity}%</p>
          </div>
        </div>

        {/* CHARTS SECTION */}
        <div style={chartsSection}>
          {/* PIE CHART */}
          <div style={chartCard}>
            <h2 style={{ color: "white" }}>Task Breakdown</h2>

            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={taskData}
                  dataKey="value"
                  outerRadius={100}
                  label
                >
                  <Cell fill="#22c55e" />
                  <Cell fill="#ef4444" />
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>

          {/* LINE CHART */}
          <div style={chartCard}>
            <h2 style={{ color: "white" }}>
              Productivity Trend
            </h2>

            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={productivityData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="day" />
                <YAxis />
                <Tooltip />
                <Line
                  type="monotone"
                  dataKey="value"
                  stroke="#60a5fa"
                  strokeWidth={3}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* PROGRESS BAR */}
        <div style={progressSection}>
          <h2 style={{ color: "white" }}>
            Productivity Progress
          </h2>

          <div style={progressBarBackground}>
            <div
              style={{
                ...progressBarFill,
                width: `${productivity}%`,
              }}
            ></div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------- STYLES ---------------- */

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background: "linear-gradient(135deg, #06B6D4, #3B82F6)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const cardContainer = {
  display: "grid",
  gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
  gap: "25px",
};

const card = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  borderRadius: "25px",
  padding: "30px",
  color: "white",
  textAlign: "center",
  boxShadow: "0 8px 32px rgba(0,0,0,0.2)",
};

const numberStyle = {
  fontSize: "42px",
  fontWeight: "bold",
  marginTop: "15px",
};

const chartsSection = {
  marginTop: "50px",
  display: "flex",
  gap: "25px",
  flexWrap: "wrap",
};

const chartCard = {
  flex: 1,
  minWidth: "300px",
  background: "rgba(255,255,255,0.12)",
  backdropFilter: "blur(15px)",
  padding: "20px",
  borderRadius: "20px",
};

const progressSection = {
  marginTop: "50px",
};

const progressBarBackground = {
  width: "100%",
  height: "35px",
  background: "rgba(255,255,255,0.2)",
  borderRadius: "20px",
  overflow: "hidden",
  marginTop: "20px",
};

const progressBarFill = {
  height: "100%",
  background: "linear-gradient(90deg, #10B981, #22C55E)",
  borderRadius: "20px",
};

export default Analytics;