import Sidebar from "../components/Sidebar";
import { useEffect, useState } from "react";
import { useTheme } from "../context/ThemeContext";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
} from "recharts";

function Dashboard() {
  const { darkMode } = useTheme();

  const [tasks, setTasks] = useState([]);
  const [studyPlans, setStudyPlans] = useState([]);
  const [student, setStudent] = useState({});

  useEffect(() => {
    setTasks(JSON.parse(localStorage.getItem("tasks")) || []);
    setStudyPlans(JSON.parse(localStorage.getItem("studyPlans")) || []);
    setStudent(JSON.parse(localStorage.getItem("studentDetails")) || {});
  }, []);

  // ---------------- COMPUTED VALUES ----------------

  const completedTasks = tasks.filter((t) => t.completed).length;

  const productivity =
    tasks.length === 0
      ? 0
      : Math.round((completedTasks / tasks.length) * 100);

  const pendingTasks = tasks.filter((t) => !t.completed);

  // ---------------- PIE CHART DATA ----------------

  const taskData = [
    { name: "Completed", value: completedTasks },
    { name: "Pending", value: tasks.length - completedTasks },
  ];

  // ---------------- REAL USER PRODUCTIVITY DATA ----------------

  const productivityData = (() => {
    const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

    const dailyStats = {};

    // Initialize days
    days.forEach((day) => {
      dailyStats[day] = {
        total: 0,
        completed: 0,
      };
    });

    tasks.forEach((task) => {
      const taskDate = task.date
        ? new Date(task.date)
        : new Date();

      const day = days[taskDate.getDay()];

      dailyStats[day].total += 1;

      if (task.completed) {
        dailyStats[day].completed += 1;
      }
    });

    return days.map((day) => ({
      day,
      value:
        dailyStats[day].total === 0
          ? 0
          : Math.round(
              (dailyStats[day].completed /
                dailyStats[day].total) *
                100
            ),
    }));
  })();

  return (
    <div
      style={{
        ...styles.container,
        background: darkMode
          ? "linear-gradient(135deg, #111827, #000000)"
          : "linear-gradient(135deg, #4F46E5, #7C3AED, #EC4899)",
      }}
    >
      <Sidebar />

      <div style={styles.content}>
        {/* HEADER */}
        <div style={styles.banner}>
          <div style={styles.overlay}>
            <h1>
              Welcome Back, {student.name || "Student"} 👋
            </h1>

            <p>
              Stay productive and achieve your goals.
            </p>
          </div>
        </div>

        {/* CARDS */}
        <div style={styles.cardGrid}>
          <div style={styles.card}>
            <h2>📚 Study Hours</h2>
            <p>{tasks.length * 2} hrs</p>
          </div>

          <div style={styles.card}>
            <h2>✅ Completed</h2>
            <p>{completedTasks}</p>
          </div>

          <div style={styles.card}>
            <h2>📝 Exams</h2>
            <p>{studyPlans.length}</p>
          </div>

          <div style={styles.card}>
            <h2>🎯 Productivity</h2>
            <p>{productivity}%</p>
          </div>
        </div>

        {/* TASKS */}
        <div style={styles.section}>
          <h2>Today's Study Plan</h2>

          {pendingTasks.length === 0 ? (
            <div style={styles.taskCard}>
              ✅ No Pending Tasks
            </div>
          ) : (
            pendingTasks.map((task, i) => (
              <div key={i} style={styles.taskCard}>
                ❌ {task.text}
              </div>
            ))
          )}
        </div>

        {/* ANALYTICS */}
        <div style={styles.section}>
          <h2>📊 Analytics Overview</h2>

          <div style={styles.chartRow}>
            {/* PIE CHART */}
            <div style={styles.chartBox}>
              <h3>Task Breakdown</h3>

              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={taskData}
                    dataKey="value"
                    outerRadius={90}
                    label
                  >
                    <Cell fill="#22c55e" />
                    <Cell fill="#ef4444" />
                  </Pie>

                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>

            {/* LINE CHART */}
            <div style={styles.chartBox}>
              <h3>Productivity Trend</h3>

              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={productivityData}>
                  <CartesianGrid
                    strokeDasharray="3 3"
                    stroke="rgba(255,255,255,0.3)"
                  />

                  <XAxis
                    dataKey="day"
                    stroke="#ffffff"
                  />

                  <YAxis
                    stroke="#ffffff"
                    domain={[0, 100]}
                  />

                  <Tooltip />

                  <Line
                    type="monotone"
                    dataKey="value"
                    stroke="#60a5fa"
                    strokeWidth={4}
                    dot={{
                      r: 5,
                      fill: "#60a5fa",
                    }}
                    activeDot={{
                      r: 8,
                    }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------- STYLES ---------------- */

const styles = {
  container: {
    display: "flex",
    minHeight: "100vh",
  },

  content: {
    marginLeft: "260px",
    width: "100%",
    padding: "25px",
  },

  banner: {
    height: "220px",
    borderRadius: "20px",
    overflow: "hidden",
    backgroundImage:
      "url('https://images.unsplash.com/photo-1498050108023-c5249f4df085')",
    backgroundSize: "cover",
    backgroundPosition: "center",
    marginBottom: "30px",
  },

  overlay: {
    height: "100%",
    background: "rgba(0,0,0,0.45)",
    color: "white",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    paddingLeft: "30px",
  },

  cardGrid: {
    display: "grid",
    gridTemplateColumns:
      "repeat(auto-fit, minmax(220px, 1fr))",
    gap: "20px",
  },

  card: {
    background: "rgba(255,255,255,0.15)",
    padding: "22px",
    borderRadius: "18px",
    color: "white",
    backdropFilter: "blur(10px)",
    boxShadow: "0 4px 20px rgba(0,0,0,0.2)",
  },

  section: {
    marginTop: "30px",
    padding: "25px",
    borderRadius: "18px",
    background: "rgba(255,255,255,0.1)",
    color: "white",
    backdropFilter: "blur(10px)",
  },

  taskCard: {
    padding: "14px",
    marginTop: "12px",
    background: "rgba(255,255,255,0.15)",
    borderRadius: "12px",
    fontSize: "16px",
  },

  chartRow: {
    display: "flex",
    gap: "25px",
    flexWrap: "wrap",
    marginTop: "20px",
  },

  chartBox: {
    flex: 1,
    minWidth: "320px",
    background: "rgba(255,255,255,0.08)",
    padding: "20px",
    borderRadius: "16px",
  },
};

export default Dashboard;