import { useState } from "react";

function TimetableGenerator() {
  const [subjects, setSubjects] = useState("");
  const [hours, setHours] = useState("");
  const [timetable, setTimetable] = useState([]);

  const generateTimetable = () => {
    const subjectList = subjects
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    const totalHours = parseInt(hours);

    if (!subjectList.length || !totalHours) {
      alert("Enter valid subjects and hours");
      return;
    }

    const result = [];
    let hour = 1;

    for (let i = 0; i < totalHours; i++) {
      const subject = subjectList[i % subjectList.length];

      result.push({
        time: `Hour ${hour}`,
        subject,
      });

      hour++;
    }

    setTimetable(result);
  };

  return (
    <div style={styles.container}>
      <h2>🤖 AI Timetable Generator</h2>

      <input
        placeholder="Enter subjects (comma separated)"
        value={subjects}
        onChange={(e) => setSubjects(e.target.value)}
        style={styles.input}
      />

      <input
        placeholder="Enter available hours"
        value={hours}
        onChange={(e) => setHours(e.target.value)}
        style={styles.input}
        type="number"
      />

      <button onClick={generateTimetable} style={styles.button}>
        Generate Timetable
      </button>

      <div style={styles.result}>
        {timetable.map((item, index) => (
          <div key={index} style={styles.card}>
            {item.time} → {item.subject}
          </div>
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
  },
  input: {
    display: "block",
    margin: "10px 0",
    padding: "10px",
    width: "300px",
  },
  button: {
    padding: "10px 15px",
    background: "#4F46E5",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  result: {
    marginTop: "20px",
  },
  card: {
    padding: "10px",
    marginTop: "5px",
    background: "#eee",
  },
};

export default TimetableGenerator;