import { Link, useNavigate } from "react-router-dom";
import { useState } from "react";

function Signup() {

  const navigate = useNavigate();

  const [name, setName] =
    useState("");

  const [email, setEmail] =
    useState("");

  const [password, setPassword] =
    useState("");

  const [confirmPassword, setConfirmPassword] =
    useState("");

  const [showPassword, setShowPassword] =
    useState(false);

  const [showConfirmPassword, setShowConfirmPassword] =
    useState(false);

  const handleSignup = () => {

    if (
      !name ||
      !email ||
      !password ||
      !confirmPassword
    ) {

      alert("Please fill all fields");
      return;

    }

    // PASSWORD MATCH CHECK

    if (
      password !==
      confirmPassword
    ) {

      alert(
        "Passwords do not match"
      );

      return;

    }

    const users =
      JSON.parse(
        localStorage.getItem(
          "users"
        )
      ) || [];

    // CHECK EXISTING USER

    const existingUser =
      users.find(
        (user) =>
          user.email === email
      );

    if (existingUser) {

      alert(
        "Email already registered"
      );

      return;

    }

    const newUser = {

      name,
      email,
      password,

    };

    users.push(newUser);

    localStorage.setItem(
      "users",
      JSON.stringify(users)
    );

    localStorage.setItem(
      "studentDetails",
      JSON.stringify(newUser)
    );

    alert(
      "Signup Successful"
    );

    navigate("/login");

  };

  return (

    <div style={mainContainer}>

      {/* DECORATION IMAGES */}

      <img
        src="https://cdn-icons-png.flaticon.com/512/3135/3135755.png"
        alt="student"
        style={studentImage}
      />

      <img
        src="https://cdn-icons-png.flaticon.com/512/2436/2436874.png"
        alt="book"
        style={bookImage}
      />

      <img
        src="https://cdn-icons-png.flaticon.com/512/2784/2784459.png"
        alt="study"
        style={studyImage}
      />

      {/* MOBILE FRAME */}

      <div style={mobileFrame}>

        {/* TOP SECTION */}

        <div style={topSection}>

          <h1 style={heading}>
            SmartStudy AI
          </h1>

          <p style={subHeading}>
            Your Personal AI Study Partner
          </p>

        </div>

        {/* FORM SECTION */}

        <div style={formSection}>

          <h2 style={title}>
            Create Account
          </h2>

          {/* NAME */}

          <input
            type="text"
            placeholder="Full Name"
            style={inputStyle}
            value={name}
            onChange={(e) =>
              setName(
                e.target.value
              )
            }
          />

          {/* EMAIL */}

          <input
            type="email"
            placeholder="Email"
            style={inputStyle}
            value={email}
            onChange={(e) =>
              setEmail(
                e.target.value
              )
            }
          />

          {/* PASSWORD */}

          <div style={passwordContainer}>

            <input
              type={
                showPassword
                  ? "text"
                  : "password"
              }
              placeholder="Password"
              style={passwordInput}
              value={password}
              onChange={(e) =>
                setPassword(
                  e.target.value
                )
              }
            />

            <button
              style={showButton}
              onClick={() =>
                setShowPassword(
                  !showPassword
                )
              }
            >
              {showPassword
                ? "🙈"
                : "👁️"}
            </button>

          </div>

          {/* CONFIRM PASSWORD */}

          <div style={passwordContainer}>

            <input
              type={
                showConfirmPassword
                  ? "text"
                  : "password"
              }
              placeholder="Confirm Password"
              style={passwordInput}
              value={confirmPassword}
              onChange={(e) =>
                setConfirmPassword(
                  e.target.value
                )
              }
            />

            <button
              style={showButton}
              onClick={() =>
                setShowConfirmPassword(
                  !showConfirmPassword
                )
              }
            >
              {showConfirmPassword
                ? "🙈"
                : "👁️"}
            </button>

          </div>

          {/* SIGNUP BUTTON */}

          <button
            style={buttonStyle}
            onClick={handleSignup}
          >
            Sign Up
          </button>

          {/* LOGIN LINK */}

          <p style={textStyle}>

            Already have an account?

            <Link
              to="/login"
              style={linkStyle}
            >
              Login
            </Link>

          </p>

        </div>

      </div>

    </div>

  );

}

/* ---------------- STYLES ---------------- */

const mainContainer = {

  height: "100vh",

  background:
    "linear-gradient(135deg, #4F46E5, #9333EA, #EC4899)",

  display: "flex",

  justifyContent: "center",

  alignItems: "center",

  position: "relative",

  overflow: "hidden",

};

const mobileFrame = {

  width: "360px",

  height: "760px",

  background:
    "rgba(255,255,255,0.12)",

  backdropFilter: "blur(15px)",

  borderRadius: "35px",

  overflow: "hidden",

  boxShadow:
    "0 10px 40px rgba(0,0,0,0.3)",

  display: "flex",

  flexDirection: "column",

  border:
    "1px solid rgba(255,255,255,0.2)",

  zIndex: 10,

};

const topSection = {

  height: "35%",

  backgroundImage:
    "url('https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=2071&auto=format&fit=crop')",

  backgroundSize: "cover",

  backgroundPosition: "center",

  color: "white",

  display: "flex",

  flexDirection: "column",

  justifyContent: "center",

  alignItems: "center",

  textAlign: "center",

  padding: "20px",

};

const heading = {

  fontSize: "34px",

  fontWeight: "bold",

};

const subHeading = {

  marginTop: "10px",

  fontSize: "16px",

};

const formSection = {

  flex: 1,

  padding: "30px 25px",

  display: "flex",

  flexDirection: "column",

  background: "white",

};

const title = {

  marginBottom: "25px",

  textAlign: "center",

  color: "#111827",

};

const inputStyle = {

  padding: "14px",

  marginBottom: "20px",

  borderRadius: "12px",

  border:
    "1px solid #D1D5DB",

  fontSize: "16px",

  outline: "none",

};

const passwordContainer = {

  display: "flex",

  alignItems: "center",

  border:
    "1px solid #D1D5DB",

  borderRadius: "12px",

  marginBottom: "20px",

  overflow: "hidden",

};

const passwordInput = {

  flex: 1,

  padding: "14px",

  border: "none",

  outline: "none",

  fontSize: "16px",

};

const showButton = {

  width: "60px",

  height: "100%",

  border: "none",

  background: "#F3F4F6",

  cursor: "pointer",

  fontSize: "18px",

};

const buttonStyle = {

  padding: "14px",

  background:
    "linear-gradient(135deg, #2563EB, #7C3AED)",

  color: "white",

  border: "none",

  borderRadius: "12px",

  fontSize: "18px",

  fontWeight: "bold",

  cursor: "pointer",

};

const textStyle = {

  marginTop: "20px",

  textAlign: "center",

  color: "#6B7280",

};

const linkStyle = {

  color: "#7C3AED",

  marginLeft: "5px",

  textDecoration: "none",

  fontWeight: "bold",

};

const studentImage = {

  position: "absolute",

  width: "120px",

  top: "40px",

  left: "60px",

};

const bookImage = {

  position: "absolute",

  width: "90px",

  bottom: "80px",

  left: "120px",

};

const studyImage = {

  position: "absolute",

  width: "100px",

  top: "120px",

  right: "80px",

};

export default Signup;