import Sidebar from "../components/Sidebar";
import { useState, useEffect } from "react";

function AIStudyAssistant() {

  const [question, setQuestion] = useState("");

  const [messages, setMessages] = useState(() => {

    const savedMessages =
      localStorage.getItem("aiMessages");

    return savedMessages
      ? JSON.parse(savedMessages)
      : [];

  });

  // SAVE CHAT
  useEffect(() => {

    localStorage.setItem(
      "aiMessages",
      JSON.stringify(messages)
    );

  }, [messages]);

  // AI RESPONSE
  const askAI = () => {

  if (question.trim() === "") {
    return;
  }

  let aiReply = "";

  const lowerQuestion =
    question.toLowerCase();

  // GREETINGS
  const greetings = [

    "hi",
    "hello",
    "hey",
    "hii",
    "good morning",
    "good afternoon",
    "good evening",
    "whatsup",
    "what's up",
    "how are you",

  ];

  // CHECK GREETINGS
  const isGreeting =
    greetings.some((word) =>
      lowerQuestion.includes(word)
    );

  // STUDY KEYWORDS
  const studyKeywords = [

    "study",
    "exam",
    "react",
    "javascript",
    "python",
    "java",
    "math",
    "science",
    "physics",
    "chemistry",
    "biology",
    "programming",
    "coding",
    "education",
    "college",
    "school",
    "assignment",
    "homework",
    "project",
    "html",
    "css",
    "database",
    "sql",
    "ai",
    "machine learning",
    "computer",
    "subject",
    "teacher",

  ];

  // CHECK STUDY QUESTION
  const isStudyQuestion =
    studyKeywords.some((word) =>
      lowerQuestion.includes(word)
    );

  // GREETING RESPONSE
  if (isGreeting) {

    aiReply =
      "Hello 👋 I am your AI Study Assistant. Ask me any study-related question 📚";

  }

  // NOT STUDY RELATED
  else if (!isStudyQuestion) {

    aiReply =
      "Please ask only study-related questions 📚";

  }

  // REACT
  else if (
    lowerQuestion.includes("react")
  ) {

    aiReply =
      "React is a JavaScript library used for building user interfaces.";

  }

  // JAVASCRIPT
  else if (
    lowerQuestion.includes("javascript")
  ) {

    aiReply =
      "JavaScript is mainly used for creating interactive websites.";

  }

  // PYTHON
  else if (
    lowerQuestion.includes("python")
  ) {

    aiReply =
      "Python is widely used in AI, web development, and data science.";

  }

  // EXAM
  else if (
    lowerQuestion.includes("exam")
  ) {

    aiReply =
      "Revise daily, solve previous papers, and practice important topics regularly.";

  }

  // STUDY
  else if (
    lowerQuestion.includes("study")
  ) {

    aiReply =
      "Study consistently with short breaks and active revision techniques.";

  }

  // MATH
  else if (
    lowerQuestion.includes("math")
  ) {

    aiReply =
      "Practice formulas and problem-solving daily to improve in Mathematics.";

  }

  // SCIENCE
  else if (
    lowerQuestion.includes("science")
  ) {

    aiReply =
      "Science concepts become easier when connected with real-life examples.";

  }

  // PROJECT
  else if (
    lowerQuestion.includes("project")
  ) {

    aiReply =
      "Projects improve practical skills and help students gain real-world experience.";

  }

  // DEFAULT STUDY RESPONSE
  else {

    aiReply =
      "This is a study-related question. Keep learning and stay productive 📘";

  }

  const updatedMessages = [

    ...messages,

    {
      type: "user",
      text: question,
    },

    {
      type: "ai",
      text: aiReply,
    },

  ];

  setMessages(updatedMessages);

  setQuestion("");
};

  // CLEAR CHAT
  const clearChat = () => {

    setMessages([]);

    localStorage.removeItem("aiMessages");
  };

  return (
    <div style={{ display: "flex" }}>

      <Sidebar />

      <div style={container}>

        <h1 style={heading}>
          AI Study Assistant 🤖
        </h1>

        <div style={chatBox}>

          {messages.length === 0 ? (

            <p style={emptyText}>
              Ask study-related questions...
            </p>

          ) : (

            messages.map((msg, index) => (

              <div
                key={index}
                style={
                  msg.type === "user"
                    ? userMessage
                    : aiMessage
                }
              >
                {msg.text}
              </div>

            ))

          )}

        </div>

        <div style={inputContainer}>

          <input
            type="text"
            placeholder="Ask your study doubt..."
            value={question}
            onChange={(e) =>
              setQuestion(e.target.value)
            }
            style={inputStyle}
          />

          <button
            style={sendButton}
            onClick={askAI}
          >
            Send
          </button>

          <button
            style={clearButton}
            onClick={clearChat}
          >
            Clear
          </button>

        </div>

      </div>

    </div>
  );
}

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg, #4F46E5, #06B6D4)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const chatBox = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  borderRadius: "20px",
  padding: "20px",
  height: "65vh",
  overflowY: "auto",
  display: "flex",
  flexDirection: "column",
  gap: "15px",
};

const userMessage = {
  alignSelf: "flex-end",
  background: "#111827",
  color: "white",
  padding: "12px 18px",
  borderRadius: "15px",
  maxWidth: "70%",
};

const aiMessage = {
  alignSelf: "flex-start",
  background: "#9333EA",
  color: "white",
  padding: "12px 18px",
  borderRadius: "15px",
  maxWidth: "70%",
};

const inputContainer = {
  marginTop: "20px",
  display: "flex",
  gap: "10px",
  flexWrap: "wrap",
};

const inputStyle = {
  flex: 1,
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
};

const sendButton = {
  padding: "14px 20px",
  background: "#111827",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
};

const clearButton = {
  padding: "14px 20px",
  background: "#EF4444",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
};

const emptyText = {
  color: "white",
  textAlign: "center",
  marginTop: "100px",
  fontSize: "18px",
};

export default AIStudyAssistant;