import Sidebar from "../components/Sidebar";
import { useState, useEffect } from "react";

function StudyPlanner() {

  const [subject, setSubject] = useState("");
  const [hours, setHours] = useState("");
  const [difficulty, setDifficulty] = useState("");

  const [plans, setPlans] = useState(() => {

    const savedPlans =
      localStorage.getItem("studyPlans");

    return savedPlans
      ? JSON.parse(savedPlans)
      : [];

  });

  // SAVE PLANS
  useEffect(() => {

    localStorage.setItem(
      "studyPlans",
      JSON.stringify(plans)
    );

  }, [plans]);

  // GENERATE PLAN
  const generatePlan = () => {

    if (
      subject.trim() === "" ||
      hours.trim() === "" ||
      difficulty.trim() === ""
    ) {
      return;
    }

    let suggestion = "";

    if (difficulty === "Easy") {

      suggestion =
        "Revise for 30 mins and solve practice questions.";

    }

    else if (difficulty === "Medium") {

      suggestion =
        "Study theory for 1 hour and practice important problems.";

    }

    else {

      suggestion =
        "Focus deeply for 2 hours with revision and mock tests.";

    }

    const newPlan = {
      subject,
      hours,
      difficulty,
      suggestion,
    };

    setPlans([...plans, newPlan]);

    setSubject("");
    setHours("");
    setDifficulty("");
  };

  // DELETE PLAN
  const deletePlan = (index) => {

    const updatedPlans =
      plans.filter((_, i) => i !== index);

    setPlans(updatedPlans);
  };

  return (
    <div style={{ display: "flex" }}>

      <Sidebar />

      <div style={container}>

        <h1 style={heading}>
          AI Study Planner 🤖📚
        </h1>

        <div style={formCard}>

          <input
            type="text"
            placeholder="Subject Name"
            value={subject}
            onChange={(e) =>
              setSubject(e.target.value)
            }
            style={inputStyle}
          />

          <input
            type="number"
            placeholder="Study Hours"
            value={hours}
            onChange={(e) =>
              setHours(e.target.value)
            }
            style={inputStyle}
          />

          <select
            value={difficulty}
            onChange={(e) =>
              setDifficulty(e.target.value)
            }
            style={inputStyle}
          >
            <option value="">
              Select Difficulty
            </option>

            <option value="Easy">
              Easy
            </option>

            <option value="Medium">
              Medium
            </option>

            <option value="Hard">
              Hard
            </option>

          </select>

          <button
            style={buttonStyle}
            onClick={generatePlan}
          >
            Generate AI Plan
          </button>

        </div>

        <div style={planGrid}>

          {plans.length === 0 ? (

            <p style={emptyText}>
              No Study Plans Generated
            </p>

          ) : (

            plans.map((item, index) => (

              <div key={index} style={planCard}>

                <h2>
                  📘 {item.subject}
                </h2>

                <p>
                  ⏰ Study Hours:
                  {" "}
                  {item.hours}
                </p>

                <p>
                  📈 Difficulty:
                  {" "}
                  {item.difficulty}
                </p>

                <div style={aiBox}>

                  <h3>
                    🤖 AI Suggestion
                  </h3>

                  <p>
                    {item.suggestion}
                  </p>

                </div>

                <button
                  style={deleteButton}
                  onClick={() =>
                    deletePlan(index)
                  }
                >
                  Delete
                </button>

              </div>

            ))

          )}

        </div>

      </div>

    </div>
  );
}

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg, #8B5CF6, #EC4899)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const formCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "25px",
  borderRadius: "20px",
  display: "flex",
  flexDirection: "column",
  gap: "15px",
};

const inputStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
};

const buttonStyle = {
  padding: "14px",
  background: "#111827",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
  fontSize: "16px",
};

const planGrid = {
  marginTop: "30px",
  display: "grid",
  gridTemplateColumns:
    "repeat(auto-fit, minmax(280px, 1fr))",
  gap: "20px",
};

const planCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "25px",
  borderRadius: "20px",
  color: "white",
};

const aiBox = {
  marginTop: "20px",
  padding: "15px",
  borderRadius: "15px",
  background: "rgba(0,0,0,0.2)",
};

const deleteButton = {
  marginTop: "20px",
  padding: "10px 15px",
  background: "#EF4444",
  border: "none",
  borderRadius: "10px",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

const emptyText = {
  color: "white",
  textAlign: "center",
  marginTop: "40px",
  fontSize: "18px",
};

export default StudyPlanner;