import {
  Link,
  useNavigate,
} from "react-router-dom";

import {
  useState,
  useEffect,
} from "react";

import { useTheme }
from "../context/ThemeContext";

function Sidebar() {

  const navigate = useNavigate();

  const {
    darkMode,
    toggleTheme,
  } = useTheme();

  // ---------------- STUDENT DATA ----------------

  const [student, setStudent] =
    useState({});

  useEffect(() => {

    const storedStudent =
      JSON.parse(
        localStorage.getItem(
          "studentDetails"
        )
      ) || {};

    setStudent(storedStudent);

  }, []);

  // ---------------- PROFILE IMAGE ----------------

  const [profileImage, setProfileImage] =
    useState(
      "https://cdn-icons-png.flaticon.com/512/3135/3135715.png"
    );

  const handleImageChange = (
    event
  ) => {

    const file =
      event.target.files[0];

    if (file) {

      const imageUrl =
        URL.createObjectURL(file);

      setProfileImage(imageUrl);

    }

  };

  // ---------------- LOGOUT ----------------

  const handleLogout = () => {

    localStorage.removeItem(
      "studentDetails"
    );

    navigate("/");

  };

  return (
    <div
      style={{
        ...sidebarStyle,

        background: darkMode
          ? "linear-gradient(180deg, #111827, #000000)"
          : "linear-gradient(180deg, #4F46E5, #7C3AED)",
      }}
    >

      <div>

        {/* PROFILE */}

        <div style={profileSection}>

          <label htmlFor="profileUpload">

            <img
              src={profileImage}
              alt="profile"
              style={profileImageStyle}
            />

          </label>

          <input
            type="file"
            id="profileUpload"
            accept="image/*"
            style={{ display: "none" }}
            onChange={
              handleImageChange
            }
          />

          {/* STUDENT NAME */}

          <h3
            style={{
              marginTop: "10px",
            }}
          >
            {student?.name || "Student"}
          </h3>

          {/* STUDENT EMAIL */}

          <p style={emailStyle}>
            {student?.email ||
              "student@gmail.com"}
          </p>

          <p style={changePhotoText}>
            
          </p>

        </div>

        {/* MENU */}

        <div style={menuStyle}>

          <Link
            style={linkStyle}
            to="/dashboard"
          >
            Dashboard
          </Link>
          <Link
  style={linkStyle}
  to="/notes"
>
  Notes Upload
</Link>

          <Link
            style={linkStyle}
            to="/planner"
          >
            Study Planner
          </Link>

          <Link
            style={linkStyle}
            to="/subjects"
          >
            Subject Manager
          </Link>

          <Link
            style={linkStyle}
            to="/assistant"
          >
            AI Study Assistant
          </Link>

          <Link
            style={linkStyle}
            to="/details"
          >
            Student Details
          </Link>

          <Link
            style={linkStyle}
            to="/analytics"
          >
            Analytics
          </Link>

          <Link
            style={linkStyle}
            to="/tasks"
          >
            Task Manager
          </Link>

        </div>

      </div>

      {/* BOTTOM BUTTONS */}

      <div>

        <button
          style={themeButton}
          onClick={toggleTheme}
        >
          {darkMode
            ? "☀️ Light Mode"
            : "🌙 Dark Mode"}
        </button>

        <button
          style={logoutButton}
          onClick={handleLogout}
        >
          Logout
        </button>

      </div>

    </div>
  );
}

/* ---------------- STYLES ---------------- */

const sidebarStyle = {
  width: "260px",
  height: "95vh",
  color: "white",
  padding: "20px",
  position: "fixed",
  top: 0,
  left: 0,
  overflowY: "auto",
  display: "flex",
  flexDirection: "column",
  justifyContent: "space-between",
};

const profileSection = {
  textAlign: "center",
  marginBottom: "40px",
};

const profileImageStyle = {
  width: "95px",
  height: "95px",
  borderRadius: "50%",
  border: "3px solid white",
  cursor: "pointer",
  objectFit: "cover",
};

const changePhotoText = {
  marginTop: "10px",
  fontSize: "12px",
  color: "#D1D5DB",
};

const emailStyle = {
  color: "#D1D5DB",
  fontSize: "14px",
};

const menuStyle = {
  display: "flex",
  flexDirection: "column",
  gap: "18px",
};

const linkStyle = {
  color: "white",
  textDecoration: "none",
  fontSize: "17px",
  padding: "12px",
  borderRadius: "10px",
  background:
    "rgba(255,255,255,0.08)",
  backdropFilter: "blur(10px)",
};

const themeButton = {
  width: "100%",
  padding: "14px",
  background: "#8B5CF6",
  border: "none",
  color: "white",
  borderRadius: "12px",
  fontSize: "16px",
  cursor: "pointer",
  fontWeight: "bold",
  marginBottom: "15px",
};

const logoutButton = {
  width: "100%",
  padding: "14px",
  background: "#EF4444",
  border: "none",
  color: "white",
  borderRadius: "12px",
  fontSize: "16px",
  cursor: "pointer",
  fontWeight: "bold",
};

export default Sidebar;