import { useState } from "react";
import Sidebar from "../components/Sidebar";

import * as pdfjsLib
from "pdfjs-dist/build/pdf";

import
"pdfjs-dist/build/pdf.worker.entry";

function NotesUpload() {

  const [questions, setQuestions] =
    useState([]);

  const [questionType, setQuestionType] =
    useState("wh");

  const [fileName, setFileName] =
    useState("");

  const [loading, setLoading] =
    useState(false);

  // ---------------- PDF TEXT EXTRACTION ----------------

  const extractTextFromPDF = async (
    file
  ) => {

    setLoading(true);

    const reader = new FileReader();

    reader.readAsArrayBuffer(file);

    reader.onload = async () => {

      try {

        const typedArray =
          new Uint8Array(
            reader.result
          );

       const pdf =
  await pdfjsLib.getDocument({
    data: typedArray,
  }).promise;

        let fullText = "";

        for (
          let i = 1;
          i <= pdf.numPages;
          i++
        ) {

          const page =
            await pdf.getPage(i);

          const content =
            await page.getTextContent();

          const strings =
            content.items.map(
              (item) => item.str
            );

          fullText +=
            strings.join(" ") + " ";

        }

        generateQuestions(fullText);

      }

      catch (error) {

        console.log(error);

        alert(
          "Error reading PDF file"
        );

      }

      setLoading(false);

    };

  };

  // ---------------- REALISTIC QUESTION GENERATOR ----------------

  const generateQuestions = (
    text
  ) => {

    const cleanedText =
      text
        .replace(/\n/g, " ")
        .replace(/\s+/g, " ");

    const sentences =
      cleanedText
        .split(".")
        .filter(
          (sentence) =>
            sentence.trim().length > 40
        )
        .slice(0, 15);

    let generatedQuestions = [];

    // ---------------- WH QUESTIONS ----------------

    if (questionType === "wh") {

      generatedQuestions =
        sentences.map(
          (
            sentence,
            index
          ) => {

            const words =
              sentence.split(" ");

            const topic =
              words
                .slice(0, 6)
                .join(" ");

            return {

              id: index,

              question:
                "Explain the concept of " +
                topic +
                ".",

            };

          }
        );

    }

    // ---------------- MCQ QUESTIONS ----------------

    else if (
      questionType === "mcq"
    ) {

      generatedQuestions =
        sentences.map(
          (
            sentence,
            index
          ) => {

            const words =
              sentence.split(" ");

            const answer =
              words[5] || "Answer";

            return {

              id: index,

              question:
                "Which of the following best relates to: " +
                words
                  .slice(0, 8)
                  .join(" ") +
                " ?",

              options: [

                answer,

                "None of the above",

                "Both A and B",

                "Cannot be determined",

              ],

            };

          }
        );

    }

    // ---------------- TRUE FALSE ----------------

    else if (
      questionType ===
      "truefalse"
    ) {

      generatedQuestions =
        sentences.map(
          (
            sentence,
            index
          ) => ({

            id: index,

            question:
              "True or False: " +
              sentence,

          })
        );

    }

    // ---------------- FILL IN THE BLANKS ----------------

    else if (
      questionType ===
      "fillups"
    ) {

      generatedQuestions =
        sentences.map(
          (
            sentence,
            index
          ) => {

            const words =
              sentence.split(" ");

            if (
              words.length > 6
            ) {

              words[4] =
                "______";

            }

            return {

              id: index,

              question:
                words.join(" "),

            };

          }
        );

    }

    setQuestions(
      generatedQuestions
    );

  };

  // ---------------- FILE UPLOAD ----------------

  const handleUpload = (
    event
  ) => {

    const file =
      event.target.files[0];

    if (!file) return;

    setFileName(file.name);

    // PDF FILE

    if (
      file.type ===
      "application/pdf"
    ) {

      extractTextFromPDF(file);

    }

    // TEXT FILE

    else {

      setLoading(true);

      const reader =
        new FileReader();

      reader.onload = (
        e
      ) => {

        generateQuestions(
          e.target.result
        );

        setLoading(false);

      };

      reader.readAsText(file);

    }

  };

  return (

    <div style={container}>

      <Sidebar />

      <div style={content}>

        {/* TITLE */}

        <h1 style={heading}>
          🤖 AI Question Generator
        </h1>

        {/* QUESTION TYPE */}

        <div style={box}>

          <h2>
            Select Question Type
          </h2>

          <select
            style={selectStyle}
            value={questionType}
            onChange={(e) =>
              setQuestionType(
                e.target.value
              )
            }
          >

            <option value="wh">
              WH Questions
            </option>

            <option value="mcq">
              Multiple Choice
            </option>

            <option value="truefalse">
              True / False
            </option>

            <option value="fillups">
              Fill in the Blanks
            </option>

          </select>

        </div>

        {/* FILE UPLOAD */}

        <div style={box}>

          <h2>
            Upload Notes / PDF
          </h2>

          <input
            type="file"
            accept=".pdf,.txt"
            onChange={
              handleUpload
            }
          />

          <p style={smallText}>
            Upload study notes,
            PDFs, or text files
          </p>

        </div>

        {/* FILE NAME */}

        {fileName && (

          <div style={box}>

            <h3>
              Uploaded File:
            </h3>

            <p>{fileName}</p>

          </div>

        )}

        {/* LOADING */}

        {loading && (

          <div style={loadingBox}>
            Generating Questions...
          </div>

        )}

        {/* GENERATED QUESTIONS */}

        <div
          style={
            questionContainer
          }
        >

          {questions.map(
            (q) => (

              <div
                key={q.id}
                style={
                  questionCard
                }
              >

                <h3>
                  Q{q.id + 1}.
                  {" "}
                  {q.question}
                </h3>

                {/* MCQ OPTIONS */}

                {q.options && (

                  <div
                    style={
                      optionContainer
                    }
                  >

                    {q.options.map(
                      (
                        option,
                        index
                      ) => (

                        <div
                          key={
                            index
                          }
                          style={
                            optionStyle
                          }
                        >

                          {option}

                        </div>

                      )
                    )}

                  </div>

                )}

                {/* TRUE FALSE */}

                {questionType ===
                  "truefalse" && (

                  <div
                    style={
                      tfContainer
                    }
                  >

                    <button
                      style={
                        tfButton
                      }
                    >
                      True
                    </button>

                    <button
                      style={
                        tfButton
                      }
                    >
                      False
                    </button>

                  </div>

                )}

              </div>

            )
          )}

        </div>

      </div>

    </div>

  );
}

/* ---------------- STYLES ---------------- */

const container = {
  display: "flex",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg,#4F46E5,#7C3AED,#EC4899)",
};

const content = {
  marginLeft: "260px",
  width: "100%",
  padding: "30px",
  color: "white",
};

const heading = {
  marginBottom: "30px",
  fontSize: "35px",
};

const box = {
  background:
    "rgba(255,255,255,0.12)",
  padding: "25px",
  borderRadius: "20px",
  marginBottom: "25px",
  backdropFilter:
    "blur(10px)",
};

const selectStyle = {
  padding: "14px",
  borderRadius: "12px",
  border: "none",
  marginTop: "15px",
  width: "260px",
  fontSize: "16px",
};

const smallText = {
  marginTop: "12px",
  color: "#E5E7EB",
};

const loadingBox = {
  background:
    "rgba(255,255,255,0.15)",
  padding: "20px",
  borderRadius: "15px",
  fontSize: "18px",
  fontWeight: "bold",
};

const questionContainer = {
  display: "flex",
  flexDirection: "column",
  gap: "20px",
  marginTop: "30px",
};

const questionCard = {
  background:
    "rgba(255,255,255,0.12)",
  padding: "25px",
  borderRadius: "18px",
  backdropFilter:
    "blur(10px)",
};

const optionContainer = {
  marginTop: "20px",
  display: "grid",
  gridTemplateColumns:
    "repeat(auto-fit,minmax(200px,1fr))",
  gap: "15px",
};

const optionStyle = {
  background:
    "rgba(255,255,255,0.18)",
  padding: "14px",
  borderRadius: "12px",
};

const tfContainer = {
  display: "flex",
  gap: "15px",
  marginTop: "20px",
};

const tfButton = {
  padding: "12px 25px",
  border: "none",
  borderRadius: "10px",
  background: "#2563EB",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

export default NotesUpload;