import Sidebar from "../components/Sidebar";
import { useState, useEffect } from "react";

function SubjectManager() {

  const [subjectName, setSubjectName] = useState("");
  const [teacher, setTeacher] = useState("");
  const [examDate, setExamDate] = useState("");
  const [notes, setNotes] = useState("");

  const [subjects, setSubjects] = useState(() => {

    const savedSubjects =
      localStorage.getItem("subjects");

    return savedSubjects
      ? JSON.parse(savedSubjects)
      : [];

  });

  // SAVE SUBJECTS
  useEffect(() => {

    localStorage.setItem(
      "subjects",
      JSON.stringify(subjects)
    );

  }, [subjects]);

  // ADD SUBJECT
  const addSubject = () => {

    if (
      subjectName.trim() === "" ||
      teacher.trim() === ""
    ) {
      return;
    }

    const newSubject = {
      subjectName,
      teacher,
      examDate,
      notes,
    };

    setSubjects([...subjects, newSubject]);

    setSubjectName("");
    setTeacher("");
    setExamDate("");
    setNotes("");
  };

  // DELETE SUBJECT
  const deleteSubject = (index) => {

    const updatedSubjects =
      subjects.filter((_, i) => i !== index);

    setSubjects(updatedSubjects);
  };

  return (
    <div style={{ display: "flex" }}>

      <Sidebar />

      <div style={container}>

        <h1 style={heading}>
          Subject Manager 📚
        </h1>

        <div style={formCard}>

          <input
            type="text"
            placeholder="Subject Name"
            value={subjectName}
            onChange={(e) =>
              setSubjectName(e.target.value)
            }
            style={inputStyle}
          />

          <input
            type="text"
            placeholder="Teacher Name"
            value={teacher}
            onChange={(e) =>
              setTeacher(e.target.value)
            }
            style={inputStyle}
          />

          <div style={{ display: "flex", flexDirection: "column" }}>

  <label style={labelStyle}>
    Exam Date
  </label>

  <input
    type="date"
    value={examDate}
    onChange={(e) =>
      setExamDate(e.target.value)
    }
    style={inputStyle}
  />

</div>

          <textarea
            placeholder="Notes"
            value={notes}
            onChange={(e) =>
              setNotes(e.target.value)
            }
            style={textareaStyle}
          />

          <button
            style={buttonStyle}
            onClick={addSubject}
          >
            Add Subject
          </button>

        </div>

        <div style={subjectGrid}>

          {subjects.length === 0 ? (

            <p style={emptyText}>
              No Subjects Added
            </p>

          ) : (

            subjects.map((item, index) => (

              <div key={index} style={subjectCard}>

                <h2>
                  {item.subjectName}
                </h2>

                <p>
                  👨‍🏫 Teacher:
                  {" "}
                  {item.teacher}
                </p>

                <p>
                  📅 Exam Date:
                  {" "}
                  {item.examDate || "Not Set"}
                </p>

                <p>
                  📝 {item.notes || "No Notes"}
                </p>

                <button
                  style={deleteButton}
                  onClick={() =>
                    deleteSubject(index)
                  }
                >
                  Delete
                </button>

              </div>

            ))

          )}

        </div>

      </div>

    </div>
  );
}

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg, #06B6D4, #3B82F6)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const formCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "25px",
  borderRadius: "20px",
  display: "flex",
  flexDirection: "column",
  gap: "15px",
  boxShadow: "0 8px 32px rgba(0,0,0,0.2)",
};

const inputStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
};
const labelStyle = {
  color: "white",
  marginBottom: "8px",
  fontWeight: "bold",
  fontSize: "16px",
};

const textareaStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
  minHeight: "100px",
};

const buttonStyle = {
  padding: "14px",
  background: "#111827",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
  fontSize: "16px",
};

const subjectGrid = {
  marginTop: "30px",
  display: "grid",
  gridTemplateColumns:
    "repeat(auto-fit, minmax(280px, 1fr))",
  gap: "20px",
};

const subjectCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  padding: "25px",
  borderRadius: "20px",
  color: "white",
  boxShadow: "0 8px 32px rgba(0,0,0,0.2)",
};

const deleteButton = {
  marginTop: "20px",
  padding: "10px 15px",
  background: "#EF4444",
  border: "none",
  borderRadius: "10px",
  color: "white",
  cursor: "pointer",
  fontWeight: "bold",
};

const emptyText = {
  color: "white",
  textAlign: "center",
  marginTop: "40px",
  fontSize: "18px",
};

export default SubjectManager;