import { Link, useNavigate } from "react-router-dom";
import { useState } from "react";

function Login() {

  const navigate = useNavigate();

  const [email, setEmail] =
    useState("");

  const [password, setPassword] =
    useState("");

  const [showPassword, setShowPassword] =
    useState(false);

  // FORGOT PASSWORD STATES

  const [showForgotBox, setShowForgotBox] =
    useState(false);

  const [forgotEmail, setForgotEmail] =
    useState("");

  const [generatedOtp, setGeneratedOtp] =
    useState("");

  const [enteredOtp, setEnteredOtp] =
    useState("");

  const [newPassword, setNewPassword] =
    useState("");

  const [confirmPassword, setConfirmPassword] =
    useState("");

  const [showNewPassword, setShowNewPassword] =
    useState(false);

  const [showConfirmPassword, setShowConfirmPassword] =
    useState(false);

  // ---------------- LOGIN ----------------

  const handleLogin = () => {

    const users =
      JSON.parse(
        localStorage.getItem("users")
      ) || [];

    const validUser =
      users.find(
        (user) =>
          user.email === email &&
          user.password === password
      );

    if (!validUser) {

      alert(
        "Invalid Email or Password. Please Signup first."
      );

      return;

    }

    localStorage.setItem(
      "studentDetails",
      JSON.stringify(validUser)
    );

    alert("Login Successful");

    navigate("/dashboard");

  };

  // ---------------- SEND OTP ----------------

  const handleSendOtp = () => {

    const users =
      JSON.parse(
        localStorage.getItem("users")
      ) || [];

    const userExists =
      users.find(
        (user) =>
          user.email === forgotEmail
      );

    if (!userExists) {

      alert(
        "Email not registered"
      );

      return;

    }

    // RANDOM OTP

    const otp =
      Math.floor(
        100000 +
        Math.random() * 900000
      ).toString();

    setGeneratedOtp(otp);

    // DEMO OTP

    alert(
      "Demo OTP Sent: " + otp
    );

  };

  // ---------------- RESET PASSWORD ----------------

  const handleResetPassword = () => {

    // OTP CHECK

    if (
      enteredOtp !== generatedOtp
    ) {

      alert("Invalid OTP");

      return;

    }

    // EMPTY PASSWORD CHECK

    if (
      !newPassword ||
      !confirmPassword
    ) {

      alert(
        "Please fill all password fields"
      );

      return;

    }

    // PASSWORD MATCH CHECK

    if (
      newPassword !==
      confirmPassword
    ) {

      alert(
        "Passwords do not match"
      );

      return;

    }

    const users =
      JSON.parse(
        localStorage.getItem("users")
      ) || [];

    // FIND USER

    const existingUser =
      users.find(
        (user) =>
          user.email === forgotEmail
      );

    // OLD PASSWORD CHECK

    if (
      existingUser.password ===
      newPassword
    ) {

      alert(
        "This password is already used. Please type a new password."
      );

      return;

    }

    // UPDATE PASSWORD

    const updatedUsers =
      users.map((user) => {

        if (
          user.email === forgotEmail
        ) {

          return {

            ...user,

            password: newPassword,

          };

        }

        return user;

      });

    localStorage.setItem(
      "users",
      JSON.stringify(updatedUsers)
    );

    alert(
      "Password Reset Successful"
    );

    // RESET STATES

    setShowForgotBox(false);

    setForgotEmail("");

    setEnteredOtp("");

    setGeneratedOtp("");

    setNewPassword("");

    setConfirmPassword("");

  };

  return (

    <div style={containerStyle}>

      <div style={overlayStyle}>

        <div style={boxStyle}>

          <h1 style={titleStyle}>
            Welcome Back
          </h1>

          {/* EMAIL */}

          <input
            type="email"
            placeholder="Email"
            style={inputStyle}
            value={email}
            onChange={(e) =>
              setEmail(
                e.target.value
              )
            }
          />

          {/* PASSWORD */}

          <div style={passwordContainer}>

            <input
              type={
                showPassword
                  ? "text"
                  : "password"
              }
              placeholder="Password"
              style={passwordInput}
              value={password}
              onChange={(e) =>
                setPassword(
                  e.target.value
                )
              }
            />

            <button
              style={showButton}
              onClick={() =>
                setShowPassword(
                  !showPassword
                )
              }
            >
              {showPassword
                ? "🙈"
                : "👁️"}
            </button>

          </div>

          {/* LOGIN BUTTON */}

          <button
            style={buttonStyle}
            onClick={handleLogin}
          >
            Login
          </button>

          {/* FORGOT PASSWORD */}

          <p
            style={forgotStyle}
            onClick={() =>
              setShowForgotBox(
                !showForgotBox
              )
            }
          >
            Forgot Password?
          </p>

          {/* FORGOT PASSWORD BOX */}

          {showForgotBox && (

            <div style={forgotBox}>

              <h3>
                Reset Password
              </h3>

              {/* EMAIL */}

              <input
                type="email"
                placeholder="Enter Registered Email"
                style={inputStyle}
                value={forgotEmail}
                onChange={(e) =>
                  setForgotEmail(
                    e.target.value
                  )
                }
              />

              {/* SEND OTP */}

              <button
                style={otpButton}
                onClick={
                  handleSendOtp
                }
              >
                Send OTP
              </button>

              {/* OTP */}

              <input
                type="text"
                placeholder="Enter OTP"
                style={inputStyle}
                value={enteredOtp}
                onChange={(e) =>
                  setEnteredOtp(
                    e.target.value
                  )
                }
              />

              {/* NEW PASSWORD */}

              <div style={passwordContainer}>

                <input
                  type={
                    showNewPassword
                      ? "text"
                      : "password"
                  }
                  placeholder="New Password"
                  style={passwordInput}
                  value={newPassword}
                  onChange={(e) =>
                    setNewPassword(
                      e.target.value
                    )
                  }
                />

                <button
                  style={showButton}
                  onClick={() =>
                    setShowNewPassword(
                      !showNewPassword
                    )
                  }
                >
                  {showNewPassword
                    ? "🙈"
                    : "👁️"}
                </button>

              </div>

              {/* CONFIRM PASSWORD */}

              <div style={passwordContainer}>

                <input
                  type={
                    showConfirmPassword
                      ? "text"
                      : "password"
                  }
                  placeholder="Confirm New Password"
                  style={passwordInput}
                  value={confirmPassword}
                  onChange={(e) =>
                    setConfirmPassword(
                      e.target.value
                    )
                  }
                />

                <button
                  style={showButton}
                  onClick={() =>
                    setShowConfirmPassword(
                      !showConfirmPassword
                    )
                  }
                >
                  {showConfirmPassword
                    ? "🙈"
                    : "👁️"}
                </button>

              </div>

              {/* RESET BUTTON */}

              <button
                style={resetButton}
                onClick={
                  handleResetPassword
                }
              >
                Reset Password
              </button>

            </div>

          )}

          {/* SIGNUP */}

          <p style={textStyle}>

            Don't have an account?

            <Link
              to="/"
              style={linkStyle}
            >
              Signup
            </Link>

          </p>

        </div>

      </div>

    </div>

  );

}

/* ---------------- STYLES ---------------- */

const containerStyle = {

  height: "100vh",

  backgroundImage:
    "url('https://images.unsplash.com/photo-1516321318423-f06f85e504b3?q=80&w=2070&auto=format&fit=crop')",

  backgroundSize: "cover",

  backgroundPosition: "center",

};

const overlayStyle = {

  height: "100%",

  width: "100%",

  background:
    "linear-gradient(rgba(79,70,229,0.6), rgba(236,72,153,0.6))",

  display: "flex",

  justifyContent: "center",

  alignItems: "center",

};

const boxStyle = {

  width: "400px",

  padding: "40px",

  borderRadius: "20px",

  backdropFilter: "blur(15px)",

  background:
    "rgba(255,255,255,0.15)",

  border:
    "1px solid rgba(255,255,255,0.3)",

  boxShadow:
    "0 8px 32px rgba(0,0,0,0.2)",

  color: "white",

};

const titleStyle = {

  textAlign: "center",

  marginBottom: "30px",

  fontSize: "32px",

};

const inputStyle = {

  width: "100%",

  padding: "14px",

  marginBottom: "20px",

  borderRadius: "10px",

  border: "none",

  outline: "none",

  fontSize: "16px",

  boxSizing: "border-box",

};

const passwordContainer = {

  display: "flex",

  alignItems: "center",

  background: "white",

  borderRadius: "10px",

  marginBottom: "20px",

  overflow: "hidden",

};

const passwordInput = {

  flex: 1,

  padding: "14px",

  border: "none",

  outline: "none",

  fontSize: "16px",

};

const showButton = {

  width: "60px",

  border: "none",

  background: "#E5E7EB",

  cursor: "pointer",

  fontSize: "18px",

};

const buttonStyle = {

  width: "100%",

  padding: "14px",

  background: "#7C3AED",

  color: "white",

  border: "none",

  borderRadius: "10px",

  fontSize: "18px",

  cursor: "pointer",

  fontWeight: "bold",

};

const forgotStyle = {

  marginTop: "15px",

  textAlign: "right",

  cursor: "pointer",

  color: "#FDE68A",

  fontWeight: "bold",

};

const forgotBox = {

  marginTop: "25px",

  padding: "20px",

  borderRadius: "15px",

  background:
    "rgba(255,255,255,0.12)",

};

const otpButton = {

  width: "100%",

  padding: "12px",

  background: "#2563EB",

  border: "none",

  borderRadius: "10px",

  color: "white",

  fontWeight: "bold",

  cursor: "pointer",

  marginBottom: "20px",

};

const resetButton = {

  width: "100%",

  padding: "12px",

  background: "#10B981",

  border: "none",

  borderRadius: "10px",

  color: "white",

  fontWeight: "bold",

  cursor: "pointer",

};

const textStyle = {

  marginTop: "20px",

  textAlign: "center",

};

const linkStyle = {

  color: "#FACC15",

  marginLeft: "5px",

  textDecoration: "none",

  fontWeight: "bold",

};

export default Login;