import Sidebar from "../components/Sidebar";
import { useState, useEffect } from "react";

function StudentDetails() {

  // EDIT MODE
  const [isEditing, setIsEditing] =
    useState(true);

  // STUDENT DATA
  const [student, setStudent] = useState(() => {

    const savedStudent =
      localStorage.getItem("studentDetails");

    return savedStudent
      ? JSON.parse(savedStudent)
      : {
          name: "",
          email: "",
          educationLevel: "",
          schoolName: "",
          className: "",
          collegeName: "",
          department: "",
          year: "",
          phone: "",
          bio: "",
          image: "",
        };

  });

  // SAVE DATA TO LOCAL STORAGE
  useEffect(() => {

    localStorage.setItem(
      "studentDetails",
      JSON.stringify(student)
    );

  }, [student]);

  // HANDLE INPUT
  const handleChange = (e) => {

    setStudent({
      ...student,
      [e.target.name]: e.target.value,
    });

  };

  // HANDLE IMAGE
  const handleImage = (e) => {

    const file = e.target.files[0];

    if (!file) return;

    const reader = new FileReader();

    reader.onloadend = () => {

      setStudent({
        ...student,
        image: reader.result,
      });

    };

    reader.readAsDataURL(file);
  };

  // SAVE DETAILS
  const handleSave = () => {

    localStorage.setItem(
      "studentDetails",
      JSON.stringify(student)
    );

    setIsEditing(false);

    alert("Details Saved Successfully ✅");
  };

  return (
    <div style={{ display: "flex" }}>

      <Sidebar />

      <div style={container}>

        <h1 style={heading}>
          Student Details 👨‍🎓
        </h1>

        <div style={profileCard}>

          {/* PROFILE IMAGE */}

          <div style={imageSection}>

            <img
              src={
                student.image ||
                "https://cdn-icons-png.flaticon.com/512/3135/3135715.png"
              }
              alt="profile"
              style={profileImage}
            />

            {isEditing && (

              <input
                type="file"
                accept="image/*"
                onChange={handleImage}
                style={fileInput}
              />

            )}

          </div>

          {/* FORM */}

          <div style={formSection}>

            <input
              type="text"
              name="name"
              placeholder="Student Name"
              value={student.name}
              onChange={handleChange}
              disabled={!isEditing}
              style={inputStyle}
            />

            <input
              type="email"
              name="email"
              placeholder="Email"
              value={student.email}
              onChange={handleChange}
              disabled={!isEditing}
              style={inputStyle}
            />

            {/* EDUCATION LEVEL */}

            <select
              name="educationLevel"
              value={student.educationLevel}
              onChange={handleChange}
              disabled={!isEditing}
              style={inputStyle}
            >

              <option value="">
                Select Education Level
              </option>

              <option value="Primary School">
                Primary School
              </option>

              <option value="High School">
                High School
              </option>

              <option value="College">
                College
              </option>

            </select>

            {/* PRIMARY SCHOOL */}

            {student.educationLevel ===
              "Primary School" && (

              <>
                <input
                  type="text"
                  name="schoolName"
                  placeholder="School Name"
                  value={student.schoolName}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />

                <input
                  type="text"
                  name="className"
                  placeholder="Class"
                  value={student.className}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />
              </>

            )}

            {/* HIGH SCHOOL */}

            {student.educationLevel ===
              "High School" && (

              <>
                <input
                  type="text"
                  name="schoolName"
                  placeholder="School Name"
                  value={student.schoolName}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />

                <input
                  type="text"
                  name="className"
                  placeholder="Grade / Class"
                  value={student.className}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />
              </>

            )}

            {/* COLLEGE */}

            {student.educationLevel ===
              "College" && (

              <>
                <input
                  type="text"
                  name="collegeName"
                  placeholder="College Name"
                  value={student.collegeName}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />

                <input
                  type="text"
                  name="department"
                  placeholder="Department"
                  value={student.department}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />

                <input
                  type="text"
                  name="year"
                  placeholder="Year"
                  value={student.year}
                  onChange={handleChange}
                  disabled={!isEditing}
                  style={inputStyle}
                />
              </>

            )}

            <input
              type="text"
              name="phone"
              placeholder="Phone Number"
              value={student.phone}
              onChange={handleChange}
              disabled={!isEditing}
              style={inputStyle}
            />

            <textarea
              name="bio"
              placeholder="Student Bio"
              value={student.bio}
              onChange={handleChange}
              disabled={!isEditing}
              style={textareaStyle}
            />

            {/* BUTTONS */}

            <div style={buttonContainer}>

              {isEditing ? (

                <button
                  style={saveButton}
                  onClick={handleSave}
                >
                  Save Details
                </button>

              ) : (

                <button
                  style={editButton}
                  onClick={() =>
                    setIsEditing(true)
                  }
                >
                  Edit Details
                </button>

              )}

            </div>

          </div>

        </div>

      </div>

    </div>
  );
}

const container = {
  marginLeft: "260px",
  padding: "30px",
  width: "100%",
  minHeight: "100vh",
  background:
    "linear-gradient(135deg, #F59E0B, #EF4444)",
};

const heading = {
  color: "white",
  marginBottom: "30px",
};

const profileCard = {
  background: "rgba(255,255,255,0.15)",
  backdropFilter: "blur(15px)",
  borderRadius: "25px",
  padding: "30px",
  display: "flex",
  flexWrap: "wrap",
  gap: "40px",
};

const imageSection = {
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
};

const profileImage = {
  width: "160px",
  height: "160px",
  borderRadius: "50%",
  objectFit: "cover",
  border: "4px solid white",
};

const fileInput = {
  marginTop: "20px",
  color: "white",
};

const formSection = {
  flex: 1,
  display: "flex",
  flexDirection: "column",
  gap: "15px",
};

const inputStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
};

const textareaStyle = {
  padding: "14px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  fontSize: "16px",
  minHeight: "120px",
};

const buttonContainer = {
  marginTop: "10px",
};

const editButton = {
  padding: "14px 25px",
  background: "#2563EB",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
};

const saveButton = {
  padding: "14px 25px",
  background: "#10B981",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
};

export default StudentDetails;