import { useEffect, useState } from "react";

const FOCUS_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

function PomodoroTimer() {

  const [time, setTime] =
    useState(FOCUS_TIME);

  const [isRunning, setIsRunning] =
    useState(false);

  const [isFocus, setIsFocus] =
    useState(true);

  useEffect(() => {

    let interval = null;

    if (isRunning) {

      interval = setInterval(() => {

        setTime((prev) => {

          if (prev <= 1) {

            if (isFocus) {

              setIsFocus(false);

              return BREAK_TIME;

            }

            else {

              setIsFocus(true);

              return FOCUS_TIME;

            }

          }

          return prev - 1;

        });

      }, 1000);

    }

    return () => {

      if (interval) {

        clearInterval(interval);

      }

    };

  }, [isRunning, isFocus]);

  const formatTime = (t) => {

    const min =
      Math.floor(t / 60);

    const sec =
      t % 60;

    return `${min}:${
      sec < 10 ? "0" : ""
    }${sec}`;

  };

  const resetTimer = () => {

    setIsRunning(false);

    setIsFocus(true);

    setTime(FOCUS_TIME);

  };

  return (

    <div style={styles.container}>

      <div style={styles.card}>

        <h2 style={styles.heading}>
          ⏳ Pomodoro Timer
        </h2>

        <h1 style={styles.timer}>
          {formatTime(time)}
        </h1>

        <h3 style={styles.mode}>

          {isFocus
            ? "🔥 Focus Time"
            : "☕ Break Time"}

        </h3>

        <div style={styles.buttons}>

          <button
            style={styles.startButton}
            onClick={() =>
              setIsRunning(!isRunning)
            }
          >

            {isRunning
              ? "Pause"
              : "Start"}

          </button>

          <button
            style={styles.resetButton}
            onClick={resetTimer}
          >
            Reset
          </button>

        </div>

      </div>

    </div>

  );

}

const styles = {

  container: {

    display: "flex",

    justifyContent: "center",

    alignItems: "center",

    padding: "30px",

    width: "100%",

  },

  card: {

    width: "350px",

    padding: "30px",

    borderRadius: "20px",

    background:
      "rgba(255,255,255,0.12)",

    backdropFilter: "blur(10px)",

    textAlign: "center",

    color: "white",

    boxShadow:
      "0 8px 20px rgba(0,0,0,0.2)",

  },

  heading: {

    marginBottom: "20px",

    fontSize: "30px",

  },

  timer: {

    fontSize: "70px",

    margin: "20px 0",

    fontWeight: "bold",

  },

  mode: {

    marginBottom: "25px",

  },

  buttons: {

    display: "flex",

    gap: "15px",

    justifyContent: "center",

  },

  startButton: {

    padding: "12px 25px",

    border: "none",

    borderRadius: "10px",

    background: "#2563EB",

    color: "white",

    fontSize: "16px",

    fontWeight: "bold",

    cursor: "pointer",

  },

  resetButton: {

    padding: "12px 25px",

    border: "none",

    borderRadius: "10px",

    background: "#EF4444",

    color: "white",

    fontSize: "16px",

    fontWeight: "bold",

    cursor: "pointer",

  },

};

export default PomodoroTimer;